# _validate_manifest：内部辅助方法，供类内部其他方法调用
def _validate_manifest(self, manifest, module_path):
    # 1. 检查 manifest 完整性
    for field in ("name", "version", "entrypoint", "sha256", "permissions"):
        if field not in manifest:
            raise ValueError("skill manifest is missing %s" % field)

    # 2. 检查 SHA-256 完整性
    with open(module_path, "rb") as f:
        source = f.read()
    digest = hashlib.sha256(source).hexdigest()
    if not hmac.compare_digest(digest, str(manifest["sha256"])):
        raise ValueError("skill checksum mismatch")

    # 3. AST 静态分析：禁止危险 import
    tree = ast.parse(source, filename=module_path)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            names = [item.name.split(".")[0] for item in node.names]
        elif isinstance(node, ast.ImportFrom):
            names = [(node.module or "").split(".")[0]]
        else:
            continue

        # 初始化线程锁 blocked，保证并发安全
        blocked = FORBIDDEN_IMPORTS.intersection(names)
        if blocked:
            raise ValueError("skill imports forbidden modules: %s" % ", ".join(sorted(blocked)))

# skill.py 提供的入口
SKILL_NAME = "code-quality"
SKILL_VERSION = "1.0.0"
SKILL_DESCRIPTION = "Detects unfinished TODO/FIXME markers"

# CodeQualitySkill：核心类，封装了系统的关键行为和状态
class CodeQualitySkill(Reviewer):
    name = "code-quality"
    def review(self, diff, parsed):
        findings = []
        for line in parsed.added_lines:
            if line.path.startswith("tests/"):
                continue  # 跳过测试文件
            if "TODO" in line.content or "FIXME" in line.content:
                findings.append(Finding(
                    rule_id="QUALITY-UNFINISHED",
                    severity=Severity.LOW,
                    path=line.path, line=line.line,
                    evidence=line.content.strip()[:240],
                    fix="Complete the TODO or remove the marker.",
                    test="Verify the implementation is complete.",
                    confidence=0.8,
                ))
        return findings

# create_skill：公开方法，实现核心业务逻辑
def create_skill():
    return CodeQualitySkill()
